/**
 * Payment Service — Payment intent creation, webhook handling, status checks.
 * Gateway: Stripe
 * Generated by BackendForge
 */
const { env } = require('../config/env');
const { getPaymentGateway } = require('../config/payment');
const { ApiError } = require('../middleware/error-handler.middleware');
const { Order, Payment } = require('../models');

const paymentService = {
  /**
   * Create a payment intent/order with the configured gateway.
   */
  async createPaymentIntent(userId, { orderId, gateway }) {
    const order = await Order.findOne({ where: { id: orderId, userId } });

    if (!order) throw ApiError.notFound('Order not found');
    if (order.paymentStatus === 'paid') throw ApiError.badRequest('Order is already paid');

    const { type, client } = getPaymentGateway(gateway);

    if (type === 'stripe') {
      const session = await client.checkout.sessions.create({
        payment_method_types: ['card'],
        mode: 'payment',
        line_items: [{
          price_data: {
            currency: (order.currency || 'inr').toLowerCase(),
            product_data: { name: `Order ${order.orderNumber}` },
            unit_amount: Math.round(parseFloat(order.totalAmount) * 100),
          },
          quantity: 1,
        }],
        metadata: {
          orderId: order.id,
          userId,
        },
        success_url: `${env.FRONTEND_URL}/orders/${order.id || order._id}?payment=success`,
        cancel_url: `${env.FRONTEND_URL}/orders/${order.id || order._id}?payment=cancelled`,
      });

      // Save payment record
      await Payment.create({
        orderId: order.id,
        userId,
        gateway: 'stripe',
        gatewayPaymentId: session.id,
        amount: order.totalAmount,
        currency: order.currency || 'INR',
        status: 'created',
        method: 'card',
      });

      await order.update({ paymentGateway: 'stripe', gatewayOrderId: session.id, paymentStatus: 'processing' });

      return { sessionId: session.id, url: session.url };
    }


    throw ApiError.badRequest('Invalid payment gateway');
  },

  /**
   * Get payment status for an order.
   */
  async getPaymentStatus(orderId, userId) {
    const payment = await Payment.findOne({
      where: { orderId, userId },
      order: [['createdAt', 'DESC']],
    });
    if (!payment) throw ApiError.notFound('No payment found for this order');
    return payment;
  },

  /**
   * Handle successful payment (called by webhook handler).
   */
  async handlePaymentSuccess(orderId, gatewayPaymentId, gateway) {
    await Order.update(
      { paymentStatus: 'paid', gatewayPaymentId, shippingStatus: 'confirmed' },
      { where: { id: orderId } }
    );
    await Payment.update(
      { status: 'captured', gatewayPaymentId },
      { where: { orderId, gateway } }
    );
  },

  /**
   * Handle failed payment (called by webhook handler).
   */
  async handlePaymentFailure(orderId, gateway, reason) {
    await Order.update({ paymentStatus: 'failed' }, { where: { id: orderId } });
    await Payment.update(
      { status: 'failed', metadata: { failureReason: reason } },
      { where: { orderId, gateway } }
    );
  },
};

module.exports = paymentService;
